import SwiftUI

// MARK: - Bakery art
//
// Every picture in the bakery is vector shapes in App/Resources/Games/Bakery/bakery.json, generated by
// tools/bakery/build.py (preview it with the contact-sheet helpers there). A shape names its colors by role:
// "c" is the color the sprite is drawn in (a flavor, a frosting, a candy color), with ".s" shade, ".l" light,
// ".d" deep, ".o" outline; or a fixed "#RRGGBB". The shade math is `Shades` (shared with Dress Up).

struct BakeShape {
    let path: Path
    let bounds: CGRect
    let fill: Paint?
    let gradient: (Paint, Paint)?
    let stroke: Paint?
    let width: CGFloat
    let opacity: Double
    let evenOdd: Bool
}

struct TierGeom {
    let hw: CGFloat, b: CGFloat, t: CGFloat, ry: CGFloat
}

final class BakeryArt {
    static let shared = BakeryArt()

    let sprites: [String: [BakeShape]]
    let tinted: Set<String>
    let tiers: [TierGeom]
    let scoopY0: CGFloat
    let scoopDY: CGFloat

    private init() {
        var file: RawBakeryFile?
        if let url = GameFiles.url("bakery", "json", game: "Bakery"), let data = try? Data(contentsOf: url) {
            file = try? JSONDecoder().decode(RawBakeryFile.self, from: data)
        }
        guard let f = file else {
            sprites = [:]; tinted = []
            tiers = [TierGeom(hw: 170, b: 518, t: 400, ry: 44), TierGeom(hw: 128, b: 400, t: 300, ry: 33), TierGeom(hw: 92, b: 300, t: 216, ry: 24)]
            scoopY0 = 372; scoopDY = 80
            return
        }
        var all: [String: [BakeShape]] = [:]
        for (name, shapes) in f.sprites {
            all[name] = shapes.map { r in
                let path = PathParser.parse(r.d)
                var grad: (Paint, Paint)?
                if let g = r.g, g.count == 2, let a = Paint(g[0]), let b = Paint(g[1]) { grad = (a, b) }
                return BakeShape(path: path, bounds: path.boundingRect, fill: Paint(r.f), gradient: grad, stroke: Paint(r.s),
                                 width: CGFloat(r.w ?? 5), opacity: r.o ?? 1, evenOdd: (r.eo ?? 0) != 0)
            }
        }
        sprites = all
        tinted = Set(f.tinted)
        tiers = f.meta.tiers.map { TierGeom(hw: CGFloat($0.hw), b: CGFloat($0.b), t: CGFloat($0.t), ry: CGFloat($0.ry)) }
        scoopY0 = CGFloat(f.meta.scoopY0)
        scoopDY = CGFloat(f.meta.scoopDY)
    }

    /// Draws one sprite into `ctx` (already in the sprite's own coordinates), in color `c`.
    func draw(_ name: String, _ c: RGB = RGB(1, 1, 1), in ctx: GraphicsContext) {
        guard let shapes = sprites[name] else { return }
        let paints = PaintSet(main: c, accent: c, skin: c, pattern: nil)
        for s in shapes {
            var g = ctx
            if s.opacity < 1 { g.opacity = s.opacity }
            let style = FillStyle(eoFill: s.evenOdd)
            if let gr = s.gradient {
                g.fill(s.path, with: .linearGradient(
                    Gradient(colors: [gr.0.resolve(paints).color, gr.1.resolve(paints).color]),
                    startPoint: CGPoint(x: s.bounds.minX, y: s.bounds.minY),
                    endPoint: CGPoint(x: s.bounds.minX, y: s.bounds.maxY)), style: style)
            } else if let fl = s.fill {
                g.fill(s.path, with: .color(fl.resolve(paints).color), style: style)
            }
            if let st = s.stroke {
                g.stroke(s.path, with: .color(st.resolve(paints).color),
                         style: StrokeStyle(lineWidth: s.width, lineCap: .round, lineJoin: .round))
            }
        }
    }

    /// Draws a sprite centered at `at` (for sprites drawn around 0,0 such as toppings).
    func draw(_ name: String, _ c: RGB, at p: CGPoint, scale: CGFloat = 1, rotation: Double = 0, in ctx: GraphicsContext) {
        var g = ctx
        g.translateBy(x: p.x, y: p.y)
        if rotation != 0 { g.rotate(by: .degrees(rotation)) }
        if scale != 1 { g.scaleBy(x: scale, y: scale) }
        draw(name, c, in: g)
    }

    static func fit(_ ctx: inout GraphicsContext, box: CGRect, into size: CGSize) {
        let s = min(size.width / box.width, size.height / box.height)
        ctx.translateBy(x: (size.width - box.width * s) / 2, y: (size.height - box.height * s) / 2)
        ctx.scaleBy(x: s, y: s)
        ctx.translateBy(x: -box.minX, y: -box.minY)
    }
}

/// One sprite as a view, fitted into its frame.
struct Sprite: View {
    let name: String
    var color: RGB = RGB(1, 1, 1)
    var box: CGRect = CGRect(x: 0, y: 0, width: 160, height: 160)

    init(_ name: String, color: RGB = RGB(1, 1, 1), box: CGRect = CGRect(x: 0, y: 0, width: 160, height: 160)) {
        self.name = name; self.color = color; self.box = box
    }

    var body: some View {
        Canvas { ctx, size in
            var g = ctx
            BakeryArt.fit(&g, box: box, into: size)
            BakeryArt.shared.draw(name, color, in: g)
        }
    }
}

enum Box {
    static let topping = CGRect(x: -50, y: -50, width: 100, height: 100)
    static let customer = CGRect(x: 0, y: 0, width: 400, height: 440)
    static let thing = CGRect(x: 0, y: 0, width: 160, height: 160)
    static let bowl = CGRect(x: 0, y: 0, width: 400, height: 300)
    static let oven = CGRect(x: 0, y: 0, width: 480, height: 460)
    static let pan = CGRect(x: 0, y: 0, width: 300, height: 150)
    static let stage = CGRect(x: 0, y: 0, width: 600, height: 600)
    static let window = CGRect(x: 0, y: 0, width: 320, height: 260)
    static let thought = CGRect(x: 0, y: 0, width: 300, height: 270)
}

// MARK: JSON

private struct RawBakeShape: Decodable {
    let d: String
    let f: String?
    let s: String?
    let w: Double?
    let o: Double?
    let g: [String]?
    let eo: Int?
}

private struct RawTier: Decodable {
    let hw: Double, b: Double, t: Double, ry: Double
}

private struct RawBakeryMeta: Decodable {
    let tiers: [RawTier]
    let scoopY0: Double
    let scoopDY: Double
}

private struct RawBakeryFile: Decodable {
    let sprites: [String: [RawBakeShape]]
    let tinted: [String]
    let meta: RawBakeryMeta
}
